L001475	\sec{Integral families}
L001476	The first three categories of integral families {(P, NP1, NP2)} share a common schematic form:
L001477	\begin{align}\label{integralSchematic}
L001478	  {\cal I}_{\{n\}}^{\{\sigma\}}
L001479	  =
L001480	  \int_{\ell_1\ell_2\ell_3\ell_4}\!\!\!\!\!\!\!\!
L001481	  \frac{
L001482	    \prod_{i=1}^{2}\dd^{(\bar{n}_i\!-\!1)}(\ell_i\cdot v_1)
L001483	
L001484	    \prod_{j=3}^{4}\dd^{(\bar{n}_j\!-\!1)}(\ell_j\cdot v_2)
L001485	
L001486	    }{
L001487	    \prod_{i}D_{i}^{n_{i}}(\sigma_{i})
L001488	    \prod_{I<J}D_{IJ}^{n_{IJ}}
L001489	    }\,,
L001490	\end{align}
L001491	where $\{\sigma\}$ and $\{n\}$ are collections of $\i 0^+$ signs and integer powers of propagators, respectively. We also write $\int_{\ell}= \int\!\!\frac{\mathrm d^{D}\ell}{(2\pi)^{D}}$
L001492	as well as $\dd^{n}(x)=2\pi (\partial/\partial x)^{n}\delta(x)$.
L001493	There are six possible worldline propagators:
L001494	\begin{align}
L001495	\begin{aligned}
L001496	  D_1(\sigma_1)&=\ell_1\cdot v_2+\sigma_1 \i 0^+\,, \qquad\qquad
L001497	  D_2(\sigma_2)=\ell_2\cdot v_2+\sigma_2 \i 0^+\,,\qquad \qquad
L001498	  D_3(\sigma_3)=(\ell_1-\ell_2)\cdot v_2+\sigma_3\i 0^+\,,\\
L001499	  D_4(\sigma_4)&=\ell_3\cdot v_1+\sigma_4 \i 0^+\,, \qquad\qquad
L001500	  D_5(\sigma_5)=\ell_4\cdot v_1+\sigma_5 \i 0^+\,, \qquad\qquad
L001501	  D_6(\sigma_6)=(\ell_3-\ell_4)\cdot v_1+\sigma_6 \i 0^+\,.
L001502	\end{aligned}
L001503	\end{align}
L001504	The massless bulk propagators $D_{IJ}$ with $I=(0,i,q)$ are (ignoring the Feynman $\i 0^{+}$ prescription)
L001505	\begin{align}\label{DIJs}
L001506	  D_{ij}&=(\ell_i-\ell_j)^2
L001507	  \,,&
L001508	  D_{qi}&=(\ell_i+q)^2
L001509	  \,,&
L001510	  D_{0i}&=\ell_i^2
L001511	  \,.
L001512	\end{align}
L001513	Inclusion of six worldline propagators $D_i$ makes this an over-complete basis, as those propagators satisfy linear identities.
L001514	These imply partial fractions:
L001515	\begin{align}\label{partialFractions}
L001516	\begin{aligned}
L001517	  \frac{1}{D_1(\sigma_1)D_2(\sigma_2)}=\frac{1}{D_2(\sigma_2)D_3(\sigma_3)}-\frac{1}{D_1(\sigma_1)D_3(\sigma_3)}\,,\qquad
L001518	  \frac{1}{D_4(\sigma_4)D_5(\sigma_5)}=\frac{1}{D_5(\sigma_5)D_6(\sigma_6)}-\frac{1}{D_4(\sigma_4)D_6(\sigma_6)}\,,
L001519	\end{aligned}
L001520	\end{align}
L001521	which hold regardless of the $\i0^+$ prescriptions ($\sigma_i$).
L001522	
L001523	In order to perform IBP reductions, we identify three subsets of the
L001524	worldline propagators corresponding to the {P, NP1, and NP2 integral families:
L001525	\begin{subequations}\label{extendedFamilies}
